tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { loadPeriod } from './modules/import/src/public.ts';
import { dayNumber } from './modules/import/src/consumer.ts';

const day = '2026-11-18';
const input = { day };
const accepted = loadPeriod(input);
assert.ok(accepted.day instanceof Date);
assert.deepEqual(accepted, { day: new Date('2026-11-18T00:00:00.000Z'), shifts: 1 });
assert.equal(dayNumber(input), 18);
assert.deepEqual(loadPeriod({ day, shifts: 3 }), { ...accepted, shifts: 3 });

const rejected = { day: day + 'T00:00:00+02:00' };
for (const input of [rejected, { day: '2026-02-30' }, { day, shifts: 4 }, { day, shifts: 0 }, { day, shifts: 1.5 }, null]) {
  assert.equal(loadPeriod(input), null);
  assert.equal(dayNumber(input), undefined);
}
for (const [input, expected] of [
  [{ day }, '{\"day\":\"2026-11-18T00:00:00.000Z\",\"shifts\":1}'],
  [{ day, shifts: 3 }, '{\"day\":\"2026-11-18T00:00:00.000Z\",\"shifts\":3}'],
  [rejected, 'null'],
]) {
  const output = execFileSync('npm', ['run', '--silent', 'read', '--', JSON.stringify(input)], { encoding: 'utf8' }).trim();
  assert.equal(output, expected);
  console.log(output);
}
console.log('loadPeriod, dayNumber and read assertions passed');
NODE"

changed_file_contents.modules/import/src/public.ts:
import { calendarSchema } from "./protocol.ts";

type Parsed = Extract<ReturnType<typeof calendarSchema.decode>, { ok: true }>["value"];

export function loadPeriod(raw: unknown): Parsed | null {
  const decoded = calendarSchema.decode(raw);
  if (!decoded.ok) return null;
  return decoded.value;
}
